import {safe,filePicker,toast} from '../app/utils.js';
export const LYRIC_STYLES=['EDITORIAL KINETIC','TYPE IMPACT','SIGNAL TYPE','SPATIAL TYPE','FLUID LETTERFORMS','TYPE PARTICLES'];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function lyricTime(s){const p=String(s).trim().replace(',','.').split(':').map(Number);if(p.some(x=>!Number.isFinite(x)))return NaN;return p.reduce((a,v)=>a*60+v,0);}
export function parseLyrics(text){text=String(text).replace(/\r/g,'').slice(0,60000);const cues=[];
 if(text.includes('-->')){for(const block of text.split(/\n\s*\n/)){const lines=block.split('\n'),i=lines.findIndex(x=>x.includes('-->'));if(i<0)continue;const [a,b]=lines[i].split('-->');const start=lyricTime(a),end=lyricTime(b.trim().split(/\s/)[0]);const content=lines.slice(i+1).join('\n').replace(/<[^>]*>/g,'');if(Number.isFinite(start)&&end>start&&content)cues.push({start,end,text:content});}}
 else{for(const line of text.split('\n')){const times=[...line.matchAll(/\[(\d+:\d+(?:\.\d+)?)\]/g)];if(times.length){const content=line.replace(/\[[^\]]*\]/g,'');const words=[...content.matchAll(/<(\d+:\d+(?:\.\d+)?)>([^<]+)/g)].map(m=>({start:lyricTime(m[1]),text:m[2].trim()}));for(const m of times)cues.push({start:lyricTime(m[1]),end:null,text:content.replace(/<[^>]*>/g,'').trim(),...(words.length?{words}: {})});}else if(line.trim()&&!/^\[.*\]$/.test(line.trim()))cues.push({start:cues.length*3,end:null,text:line.trim(),estimated:true});}}
 cues.sort((a,b)=>a.start-b.start);for(let i=0;i<cues.length;i++){cues[i].end??=Math.max(cues[i].start+.1,cues[i+1]?.start??cues[i].start+3);}
 return cues.slice(0,200);
}
export function lyricsSettings(s={}){return {enabled:!!s.enabled,style:clamp(Math.floor(s.style||0),0,5),x:clamp(Number(s.x)||0,-.8,.8),y:clamp(Number(s.y)||0,-.8,.8),rotation:clamp(Number(s.rotation)||0,-180,180),scale:clamp(Number(s.scale)||1,.2,2),overshoot:clamp(Number(s.overshoot??.35),0,1),offset:clamp(Number(s.offset)||0,-60,60),amount:clamp(Number(s.amount??1),0,2),entry:clamp(Number(s.entry??.5),.05,2),exit:clamp(Number(s.exit??.4),.05,2),cues:(Array.isArray(s.cues)?s.cues:[]).slice(0,200).filter(c=>Number.isFinite(c.start)&&Number.isFinite(c.end)&&c.start>=0&&c.end>c.start).map(c=>({...c,text:String(c.text||'').slice(0,500),words:Array.isArray(c.words)?c.words.filter(w=>Number.isFinite(w.start)&&w.start>=c.start&&w.start<c.end).map(w=>({start:w.start,text:String(w.text).slice(0,100)})):undefined}))};}
export function activeLyric(settings,time){const t=time-settings.offset;let index=-1;for(let i=0;i<settings.cues.length;i++)if(t>=settings.cues[i].start&&t<settings.cues[i].end)index=i;return index;}
export function lyricsHTML(lab){const l=lab.lyrics;return `<details class="inspector-block lyrics-block" open><summary>LYRICS MOTION / TIMED TYPE</summary><label class="mask-check"><input id="lyrics-enabled" type="checkbox" ${l.enabled?'checked':''}> ENABLE LYRICS MOTION</label><select id="lyrics-style" aria-label="Lyrics animation">${LYRIC_STYLES.map((s,i)=>`<option value="${i}" ${l.style===i?'selected':''}>${s}</option>`).join('')}</select><p class="micro-note">LRC · enhanced LRC words · SRT · VTT · plain text. Plain text starts with editable 3-second placeholders, not automatic alignment.</p><textarea id="lyrics-input" aria-label="Lyrics text or timecodes" rows="4" placeholder="[00:00.00] FIRST LINE&#10;[00:03.00] СЛЕДУЮЩАЯ СТРОКА"></textarea><div class="lyrics-actions"><button id="lyrics-import" class="toolbtn">IMPORT TEXT</button><button id="lyrics-apply" class="toolbtn">APPLY TEXT</button></div><div class="lyrics-actions"><button id="lyrics-prev" class="toolbtn">← PREVIOUS</button><button id="lyrics-next" class="toolbtn">NEXT →</button><button id="lyrics-tap" class="toolbtn">TAP NEXT START</button><button id="lyrics-add" class="toolbtn">ADD MARKER</button></div><p class="micro-note">Tap records track time for the selected line and advances. Click a line number to seek. Word timing uses imported enhanced LRC timestamps only.</p><div id="lyrics-cues">${l.cues.map((c,i)=>`<div class="lyric-cue"><button class="toolbtn" data-lyric-seek="${i}" aria-label="Preview lyric ${i+1}">${i+1}</button><input aria-label="Line ${i+1} start" data-cue="${i}:start" type="number" min="0" step=".01" value="${c.start.toFixed(2)}"><input aria-label="Line ${i+1} end" data-cue="${i}:end" type="number" min="0" step=".01" value="${c.end.toFixed(2)}"><textarea aria-label="Line ${i+1} text" data-cue="${i}:text" rows="2">${safe(c.text)}</textarea></div>`).join('')}</div>${[['x','Position X',-.8,.8,.01],['y','Position Y',-.8,.8,.01],['scale','Composition scale',.2,2,.01],['rotation','Rotation / degrees',-180,180,1],['overshoot','Impact overshoot',0,1,.01],['offset','Offset / seconds',-60,60,.01],['amount','Motion intensity',0,2,.01],['entry','Entry / seconds',.05,2,.01],['exit','Exit / seconds',.05,2,.01]].map(([k,label,min,max,step])=>`<label class="input-label">${label}<input data-lyrics-setting="${k}" aria-label="Lyrics ${label}" type="number" min="${min}" max="${max}" step="${step}" value="${l[k]}"></label>`).join('')}<p id="lyrics-status" class="micro-note">${l.cues.length} TIMED LINES</p></details>`;}
export function bindLyrics(lab){const q=s=>lab.root.querySelector(s),l=lab.lyrics;if(!q('#lyrics-enabled'))return;const commit=()=>{lab.lyricRenderer?.clear();lab.update()};const clock=()=>lab.source.element?lab.source.time:lab.elapsed;const seek=i=>{lab.lyricSelected=clamp(i,0,Math.max(0,l.cues.length-1));const c=l.cues[lab.lyricSelected];if(!c)return;if(lab.source.element)lab.source.element.currentTime=c.start+l.offset;else lab.elapsed=c.start+l.offset;q('#lyrics-status').textContent='SELECTED LINE '+(lab.lyricSelected+1);};
 q('#lyrics-enabled').onchange=e=>{l.enabled=e.target.checked;if(!l.enabled)lab.rebuildTextTexture();commit()};q('#lyrics-style').onchange=e=>{l.style=Number(e.target.value);commit()};
 const apply=text=>{const cues=parseLyrics(text);if(!cues.length){toast('No valid lyric lines found','error');return;}lab.capture();l.cues=cues;l.enabled=true;lab.lyricSelected=0;lab.render();commit()};
 q('#lyrics-apply').onclick=()=>apply(q('#lyrics-input').value);q('#lyrics-import').onclick=async()=>{const [file]=await filePicker('.txt,.lrc,.srt,.vtt');if(file){if(file.size>100000){toast('Text limit: 100 KB','error');return;}apply(await file.text())}};
 for(const el of lab.root.querySelectorAll('[data-cue]'))el.onchange=()=>{const [i,k]=el.dataset.cue.split(':'),cue=l.cues[Number(i)],v=k==='text'?el.value:Number(el.value);if(k!=='text'&&(!Number.isFinite(v)||v<0||(k==='start'?v>=cue.end:v<=cue.start))){el.value=cue[k];toast('End must be after start','error');return;}lab.capture();cue[k]=v;if(k==='text')delete cue.words;commit()};
 for(const el of lab.root.querySelectorAll('[data-lyrics-setting]'))el.onchange=()=>{const k=el.dataset.lyricsSetting;l[k]=Number(el.value);Object.assign(l,lyricsSettings(l));el.value=l[k];commit()};
 for(const el of lab.root.querySelectorAll('[data-lyric-seek]'))el.onclick=()=>seek(Number(el.dataset.lyricSeek));q('#lyrics-prev').onclick=()=>seek((lab.lyricSelected||0)-1);q('#lyrics-next').onclick=()=>seek((lab.lyricSelected||0)+1);
 q('#lyrics-tap').onclick=()=>{const i=lab.lyricSelected||0,c=l.cues[i];if(!c)return;lab.capture();const t=Math.max(0,clock()-l.offset);c.start=t;c.end=Math.max(t+.1,l.cues[i+1]?.start??t+3);if(i&&l.cues[i-1].start<t)l.cues[i-1].end=t;lab.lyricSelected=Math.min(i+1,l.cues.length-1);lab.render();commit()};
 q('#lyrics-add').onclick=()=>{lab.capture();const start=Math.max(0,clock()-l.offset);l.cues.push({start,end:start+3,text:'NEW LINE'});lab.render();commit()};
}
export class LyricsRenderer{
 constructor(){this.canvas=document.createElement('canvas');this.cache=new Map();}
 clear(){this.cache.clear();}
 glyph(text,w,h,font,layout){const key=[text,w,h,font,JSON.stringify(layout)].join('|');if(this.cache.has(key))return this.cache.get(key);const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d',{willReadFrequently:true});let size=h*.24*(layout.size||1),lines=text.split('\n');g.textAlign=layout.align||'center';g.textBaseline='middle';g.letterSpacing=((layout.tracking||0)*w/1024)+'px';const leading=layout.lineHeight||1.15;g.font=font.replace(/\d+px/,size+'px');while((Math.max(...lines.map(line=>g.measureText(line).width))>w*.86||lines.length*size*leading>h*.72)&&size>10){size*=.95;g.font=font.replace(/\d+px/,size+'px');}g.fillStyle='#fff';const x=g.textAlign==='left'?w*.07:g.textAlign==='right'?w*.93:w*.5;lines.forEach((line,i)=>g.fillText(line,x,h*.5+(i-(lines.length-1)/2)*size*leading));const pixels=g.getImageData(0,0,w,h).data,points=[],step=Math.max(5,Math.round(w/200));for(let y=0;y<h;y+=step)for(let x=0;x<w;x+=step)if(pixels[(y*w+x)*4+3]>100)points.push([x,y]);const value={c,points,step};if(this.cache.size>=6)this.cache.delete(this.cache.keys().next().value);this.cache.set(key,value);return value;}
 render(settings,time,w,h,font,layout,signals={},params=[1,1,1,1,1,1,1,0]){const c=this.canvas;if(c.width!==w||c.height!==h){c.width=w;c.height=h;this.clear();}const g=c.getContext('2d');g.clearRect(0,0,w,h);const index=activeLyric(settings,time);if(index<0)return c;const cue=settings.cues[index],local=time-settings.offset-cue.start,duration=cue.end-cue.start;
 let text=cue.text;if(cue.words?.length){const words=cue.words.filter(word=>word.start<=time-settings.offset);text=words.map(x=>x.text).join(' ');if(!text)return c;}
 const {c:glyph,points,step}=this.glyph(text,w,h,font,layout),entry=clamp(local/Math.min(settings.entry,duration*.45),0,1),exit=clamp((duration-local)/Math.min(settings.exit,duration*.45),0,1),ease=1-Math.pow(1-entry,3),amount=settings.amount*(.65+.35*params[1]),energy=(signals.bass||0)+params[2]*.025;
 g.save();g.globalAlpha=Math.min(1,exit*2);g.translate(w*(.5+settings.x),h*(.5+settings.y));g.rotate(settings.rotation*Math.PI/180);g.scale(settings.scale,settings.scale);g.scale(clamp(params[0],.3,2),clamp(params[0],.3,2));const style=settings.style;
 if(style===0){g.rotate((1-ease)*-.08*amount);const scale=.88+.12*ease+energy*.025*amount;g.scale(scale,scale);g.beginPath();g.rect(-w/2,-h/2,w,h*ease);g.clip();g.drawImage(glyph,-w/2,-h/2+(1-ease)*h*.25*amount);}
 else if(style===1){const spring=1+Math.sin(entry*Math.PI*3)*Math.exp(-entry*5)*settings.overshoot*amount;g.scale(spring*(1+energy*.035),1/spring);g.rotate((1-ease)*.09*(index%2?1:-1));g.drawImage(glyph,-w/2,-h/2);}
 else if(style===2){const bands=36,sh=h/bands;for(let i=0;i<bands;i++){const jitter=Math.sin(i*39.7+Math.floor(local*15))*(1-ease)*w*.22*amount*(.3+params[5]);g.globalAlpha=clamp(ease*1.5-(i%5)*.08,0,1)*exit;g.drawImage(glyph,0,i*sh,w,sh,-w/2+jitter,-h/2+i*sh,w,sh+1);}}
 else if(style===3){for(let layer=5;layer>=0;layer--){g.save();const z=1-layer*(.035+.03*params[4])-(1-ease)*.3;g.scale(z,z);g.globalAlpha=(layer===0?1:.12)*exit;g.transform(1,0,Math.sin(local*.7)*.12*amount,1,layer*w*.018*(1-ease+.2),layer*h*.028);g.drawImage(glyph,-w/2,-h/2);g.restore();}}
 else if(style===4){const rows=90,sh=h/rows;for(let i=0;i<rows;i++){const bend=Math.sin(i*.12-local*3)*((1-ease)*.11+energy*.014)*w*amount;g.drawImage(glyph,0,i*sh,w,sh,-w/2+bend,-h/2+i*sh,w,sh+1);}}
 else{g.fillStyle='#fff';const scatter=(1-ease+(1-exit))*amount;for(let i=0;i<points.length;i++){const [x,y]=points[i],phase=i*2.399;g.globalAlpha=exit*(.65+.35*ease);g.fillRect(x-w/2+Math.cos(phase)*w*.4*scatter,y-h/2+Math.sin(phase)*h*.8*scatter,step*(.5+.3*params[6]),step*(.5+.3*params[6]));}}
 g.restore();return c;
 }
}
